mapper.select:
select um.id, um.origin_url, um.short_url, um.expire_time, um.create_time, um.status, um.update_time, (select su.username from sys_user su, sys_user_job suj where suj.id = um.create_user_id and suj.user_id = su.id) as create_user from url_mapping um
and um.create_time >= #{params.beginDate}
and um.create_time <= #{params.endDate}
and um.status = #{params.status}
order by um.id desc
